import{_ as t,o as a,c as n,a3 as o}from"./chunks/framework.BTQ4eCVb.js";const g=JSON.parse('{"title":"Team Chat — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Team Chat — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/team-chat"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Team Chat — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/team-chat"}]]},"headers":[],"relativePath":"user-guide/team-chat.md","filePath":"user-guide/team-chat.md","lastUpdated":1788122084000}'),s={name:"user-guide/team-chat.md"};function r(i,e,d,c,l,h){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="team-chat-—-user-guide" tabindex="-1">Team Chat — User Guide <a class="header-anchor" href="#team-chat-—-user-guide" aria-label="Permalink to &quot;Team Chat — User Guide&quot;">​</a></h1><p>Install <strong>Team Chat</strong> from Marketplace (free Collaboration module). Until it is installed, the Team Chat nav item and <code>/team-chat</code> page stay hidden.</p><h2 id="who-can-use-team-chat" tabindex="-1">Who can use Team Chat? <a class="header-anchor" href="#who-can-use-team-chat" aria-label="Permalink to &quot;Who can use Team Chat?&quot;">​</a></h2><p>Workspace users with a login — owners, admins, managers, and staff — after the module is installed and their role includes the relevant permissions (at least <code>team-chat.view</code>).</p><p>Employees without a linked login cannot open EloSync, so they cannot use Team Chat.</p><p><strong>Guests</strong> (external participants without a workspace login) are not supported in this version; that is planned for a later release.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><ol><li>Open <strong>Marketplace</strong>.</li><li>Find <strong>Team Chat</strong> (Collaboration category).</li><li>Click <strong>Install</strong> (free — <code>$0</code>; not included by default on new workspaces; not billable yet).</li></ol><p>You need Marketplace purchase permission to install. After install, your role still needs Team Chat permissions (below).</p><p>On install, the workspace provisions a public <strong>#general</strong> channel and joins every active (verified, non-suspended) user automatically. Opening Team Chat later re-checks that #general exists and that active users are members.</p><h2 id="open-team-chat" tabindex="-1">Open Team Chat <a class="header-anchor" href="#open-team-chat" aria-label="Permalink to &quot;Open Team Chat&quot;">​</a></h2><p>Open <strong>Team Chat</strong> from the sidebar (<code>/team-chat</code>).</p><p>The page fills the workspace content area: channels and direct messages scroll in the left pane, the open conversation scrolls in the message list, and the composer stays pinned at the bottom. Long message history does not grow the browser page scrollbar.</p><h2 id="channels-dms-and-group-dms" tabindex="-1">Channels, DMs, and group DMs <a class="header-anchor" href="#channels-dms-and-group-dms" aria-label="Permalink to &quot;Channels, DMs, and group DMs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Behavior</th></tr></thead><tbody><tr><td><strong>Public channel</strong></td><td>Visible in the sidebar to everyone with <code>team-chat.view</code>. Join to read and post. Creating a channel requires <code>team-chat.channels.create</code>.</td></tr><tr><td><strong>Private channel</strong></td><td>Invite-only. Non-members cannot open or join; someone with <code>team-chat.channels.manage</code> adds members.</td></tr><tr><td><strong>Direct message (DM)</strong></td><td>1:1 conversation with another workspace user. Opening a DM with the same person reuses the existing thread. Anyone with <code>team-chat.view</code> can start a DM.</td></tr><tr><td><strong>Group DM</strong></td><td>Multi-person direct conversation (created with a list of users).</td></tr></tbody></table><p>#general is the default company-wide public channel. It cannot be deleted.</p><h3 id="channel-creator-settings" tabindex="-1">Channel creator settings <a class="header-anchor" href="#channel-creator-settings" aria-label="Permalink to &quot;Channel creator settings&quot;">​</a></h3><p>If you <strong>created</strong> a channel, open <strong>Channel settings</strong> (gear) in the conversation header to:</p><ul><li>Rename the channel or edit its description</li><li>Switch visibility <strong>public ↔ private</strong></li><li><strong>Permanently delete</strong> the channel and all of its history (messages, reactions, pins, and attachments) by typing the exact channel name to confirm</li></ul><p>Only the creator can change visibility or delete the channel. Deleting #general is blocked.</p><h2 id="messages" tabindex="-1">Messages <a class="header-anchor" href="#messages" aria-label="Permalink to &quot;Messages&quot;">​</a></h2><p>With <code>team-chat.messages.create</code> you can post in conversations you belong to.</p><ul><li><strong>Send</strong> — press <strong>Enter</strong> to send; <strong>Shift+Enter</strong> inserts a new line.</li><li><strong>@mentions</strong> — type <code>@</code> and pick a teammate. Mentions use the same <code>@[Name](user:id)</code> token pattern as lead notes / task comments and notify the mentioned member.</li><li><strong>Threads</strong> — reply to a message to keep a side conversation under the parent.</li><li><strong>Reactions</strong> — add or remove emoji reactions on a message.</li><li><strong>Edit / delete</strong> — authors with <code>team-chat.messages.update</code> can edit their own messages; <code>team-chat.messages.delete</code> (or update on own messages, depending on role) can remove them.</li><li><strong>Pins</strong> — pin important messages in a conversation; pinned messages are listed for everyone in that room.</li><li><strong>Typing</strong> — teammates see when someone is typing in the open conversation (realtime over Reverb).</li><li><strong>Attachments</strong> — upload files on a message; files are stored on the workspace object storage disk (S3 in production) under a Team Chat path and downloaded through the app (not a public URL).</li><li><strong>Search</strong> — search message text across conversations you can access (<code>mod+f</code> focuses search on the Team Chat page).</li></ul><h2 id="notifications-and-unread" tabindex="-1">Notifications and unread <a class="header-anchor" href="#notifications-and-unread" aria-label="Permalink to &quot;Notifications and unread&quot;">​</a></h2><ul><li><strong>Bell</strong> — @mentions and new direct messages create in-app notifications (<code>team-chat.mentioned</code>, <code>team-chat.direct_message</code>). Clicking a notification deep-links into <code>/team-chat</code> for that conversation (and message when provided).</li><li><strong>Unread</strong> — each conversation shows an unread count based on messages after your last read; opening a conversation marks it read.</li></ul><p>Realtime delivery uses the existing per-user notification channel plus the conversation channel for live message updates.</p><h2 id="retention" tabindex="-1">Retention <a class="header-anchor" href="#retention" aria-label="Permalink to &quot;Retention&quot;">​</a></h2><p>Workspace admins set how long Team Chat keeps messages and attachments:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Key</th><th>Options</th></tr></thead><tbody><tr><td><strong>Message &amp; file retention</strong></td><td><code>team-chat.retention_days</code></td><td><strong>30</strong>, <strong>90</strong>, <strong>365</strong> days, or <strong>Forever</strong></td></tr></tbody></table><p>This is one workspace-wide setting (Settings → Team Chat when the module is installed). <strong>Forever</strong> keeps history indefinitely. Otherwise a scheduled purge permanently removes messages older than the window (attachments go with those messages).</p><h2 id="keyboard-shortcuts" tabindex="-1">Keyboard shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard shortcuts&quot;">​</a></h2><p>On the Team Chat page (same pattern as other modules):</p><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>n</code></td><td>Start a new conversation / channel (permission-gated)</td></tr><tr><td><code>mod+f</code> (⌘F / Ctrl+F)</td><td>Focus Team Chat search</td></tr></tbody></table><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Permission</th><th>Ability</th></tr></thead><tbody><tr><td><code>team-chat.view</code></td><td>Open Team Chat, list/join public channels, open DMs; read messages, search, and download attachments in conversations you belong to</td></tr><tr><td><code>team-chat.channels.create</code></td><td>Create public/private channels (creators can later edit visibility / delete their own channels)</td></tr><tr><td><code>team-chat.channels.manage</code></td><td>Add/remove members on channels where you are a moderator, or with this permission</td></tr><tr><td><code>team-chat.messages.create</code></td><td>Post messages, reactions, pins, attachments</td></tr><tr><td><code>team-chat.messages.update</code></td><td>Edit own messages</td></tr><tr><td><code>team-chat.messages.delete</code></td><td>Delete messages (moderators / elevated roles)</td></tr></tbody></table><p>Default role map grants full Team Chat permissions to <strong>admin</strong> and <strong>manager</strong>. <strong>Staff</strong> get view, channel create, and message create/update (not channel manage or message delete). Workspace owners (<code>superadmin</code>) receive all permissions via provisioning.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/user-guide/tenant-settings">Tenant Settings</a> — retention and other workspace settings</li><li><a href="/user-guide/tenant-application#marketplace-add--remove-modules">Marketplace</a></li></ul>',38)])])}const p=t(s,[["render",r]]);export{g as __pageData,p as default};
